query:
query ($productFilter: String!) {
  products(limit: 500, where: $productFilter) {
    count
    total
    results {
      id
      key
      masterData {
        published
        current {
          nameAllLocales {
            locale
            value
          }
          masterVariant {
            attributesRaw(
              includeNames: [
                "id"
                "displayName"
                "contractIndicator"
                "billingCode"
                "startDate"
                "endDate"
                "offerPreselectDesignation"
                "bundleProductIds"
    "qualifyingProductIds"
          "customerTypes"
                "eligibilitySalesChannels"
                "additionalEligibility"
                "reconnectEligibleOffer"
                "customerSubtypes"
                "reconnectSubscriberType"
                "offerProductType"
                "opusChannels"
                "opusSubChannels"
                "opusStoreIds"
                "salesChannel"
                "salesSubChannel"
                "locationId"
                "locationTypeId"
                "dealerCode"
                "directIntegrationPartnerName"
                "specialPage"
                "masterDealerId"
                "dealerIds"
                "eligibilityCreditRisk"
                "treatmentCode"
                "marketingSrcCode"
                "offerIntent"
                "migrationServiceType"
                "ineligiblePartners"
                "onlinePartnerDetails"
                "conflictingOffers"
                "allowConflictingOffers"
                "delayProvisioning"
                "delayProvisioningReasons"
  "serviceSubscriptionType"
                "activeSubscriptionType"
            ]
            ) {
              name
              value
              referencedResourceSet {
                ... on Product {
                  __typename
                  id
                  key
                  masterData {
                    current {
                      masterVariant {
                        attributesRaw(
                          includeNames: [
                            "feeType"
                            "displayType"
                            "compatibleProducts"
                            "includedProducts"
 "conflictingProducts"
                           "contractIndicator1"
                            "subCategory"
                            "productGroup"
                            "delayProvisioning"
                            "delayProvisioningReasons"
                          ]
                        ) {
                          name
                          value
                        }
                      }
                      allVariants {
                        attributesRaw(includeNames: ["categoryNew"]) {
                          name
                          value
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

