}

eligibilityQuery:
query {
  product(key: "epochGlobalConfigurations") {
    masterData {
      current {
        masterVariant {
          attributesRaw(includeNames: [
            "eligibilityDesign",
            "eligibilityErrorMessages"
          ]) {
            name
            value
          }
        }
      }
    }
  }
}

